SELECT country_id
FROM country
WHERE iso_code = #{isoCode}

SELECT country_id
FROM country
WHERE currency = #{curUnit}

mapper.update:
UPDATE country
SET country_name = #{countryName},
    country_en_name = #{countryEnName},
    iso_code = #{isoCode}
WHERE country_id = #{countryId}

UPDATE alert_level
SET level_value = #{levelValue}
WHERE country_id = #{countryId}
